  - calcularEfeitosMover({origem, destino, valorItem, saude?, objetivoPosicao, objetivoClasse?}) → Efeito[] com marcador 'S' | 'A' | 'F' | '§' | '=' e texto;
  - S: 'Reserva de emergência R$ 18.400,00 → R$ 34.012,40 (necessário R$ 30.000,00) · o alerta deixa de aparecer / passa a aparecer';
  - A: meta da Alocação em R$ na Emergência e em % nas outras;
