SUBGRUPOS:
- SUBGRUPOS_POR_CATEGORIA: reservas []; rendaFixaFundos [pos-fixada 'Pós-fixada', prefixada 'Pré-fixada', hibrida 'Híbrida'];
- SUBGRUPO_EDITAVEL (false nas 3);
